RichMessaging.AuthRequestResult auth = new RichMessaging.AuthRequestHandler().handleAuthRequest(new RichMessaging.AuthRequestResponse('token', '001000000000001', 'provider'));
System.assertEquals(RichMessaging.AuthRequestResultStatus.AUTHENTICATED, auth.resultStatus);
System.assertEquals('/richmessaging/authenticated', auth.redirectPageReference.getUrl());
System.assertNotEquals(null, auth.expirationDateTime);
RichMessaging.ProcessCatalogOrderResult catalog = new RichMessaging.ProcessCatalogOrderHandler().processCatalogOrderRequest(new RichMessaging.ProcessCatalogOrderRequest());
System.assertEquals(RichMessaging.ProcessCatalogOrderResultStatus.SUCCESS, catalog.resultStatus);
System.assertEquals('', catalog.errorMessage);
System.assertNotEquals('', catalog.catalogOrderReferenceId);
RichMessaging.ProcessPaymentResult payment = new RichMessaging.ProcessPaymentHandler().processPaymentRequest(new RichMessaging.ProcessPaymentRequest('txn-1', null, null, null, null, null, '001000000000001'));
System.assertEquals(RichMessaging.ProcessPaymentResultStatus.SUCCESS, payment.resultStatus);
System.assertEquals('', payment.errorMessage);

